import unittest
from subject import total


class TotalTests(unittest.TestCase):
    # 判準來源：題述規格；(2,False)=40、(3,False)=70 為已確認例子

    def test_confirmed_examples(self):
        self.assertEqual(total(2, False), 40)
        self.assertEqual(total(3, False), 70)

    def test_tier_boundaries_not_remote(self):
        # 抓邊界 off-by-one（<= 誤寫為 <）與固定回傳
        cases = {0: 40, 2: 40, 3: 70, 5: 70, 6: 100, 50: 100}
        for w, exp in cases.items():
            with self.subTest(weight=w):
                self.assertEqual(total(w, False), exp)

    def test_remote_adds_20(self):
        # 抓忽略 remote 或加錯金額
        cases = {0: 60, 2: 60, 3: 90, 5: 90, 6: 120}
        for w, exp in cases.items():
            with self.subTest(weight=w):
                self.assertEqual(total(w, True), exp)

    def test_negative_weight_rejected(self):
        # 抓缺少守衛或邊界寫成 <= 0 / < -1
        for w in (-1, -100):
            for r in (False, True):
                with self.subTest(weight=w, remote=r):
                    with self.assertRaisesRegex(ValueError, "^invalid-weight$"):
                        total(w, r)

    def test_zero_is_valid(self):
        self.assertEqual(total(0, False), 40)

